// Whole-line speech generated by installed Windows voices. Opt-in, loopback-only, no cloud or voice downloads.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {execFile,execFileSync} from 'node:child_process';
import {deliveryFor,speechSSML} from '../game/js/voice/delivery.js';
const ps=process.platform==='win32'?'powershell.exe':'/mnt/c/Windows/System32/WindowsPowerShell/v1.0/powershell.exe';
const windows=p=>process.platform==='win32'?p:execFileSync('wslpath',['-w',p],{encoding:'utf8'}).trim();
export function prepareSpeechWave(wav) {
  if(wav.length<44||wav.toString('ascii',0,4)!=='RIFF'||wav.toString('ascii',8,12)!=='WAVE')throw Error('Invalid speech wave.');
  let fmt,data;
  for(let p=12;p+8<=wav.length;){const size=wav.readUInt32LE(p+4),end=p+8+size;if(end>wav.length)throw Error('Truncated speech wave.');
    const id=wav.toString('ascii',p,p+4);if(id==='fmt ')fmt=wav.subarray(p+8,end);if(id==='data')data=wav.subarray(p+8,end);p=end+(size%2);}
  if(!fmt||fmt.length<16||fmt.readUInt16LE(0)!==1||fmt.readUInt16LE(2)!==1||fmt.readUInt16LE(14)!==16||!data||data.length%2)throw Error('Expected mono PCM speech.');
  const rate=fmt.readUInt32LE(4);if(rate<8000||rate>48000||data.length>rate*2*25)throw Error('Speech duration exceeded.');
  let lo=0,hi=data.length/2;
  while(lo<hi&&Math.abs(data.readInt16LE(lo*2))<60)lo++;
  while(hi>lo&&Math.abs(data.readInt16LE((hi-1)*2))<60)hi--;
  lo=Math.max(0,lo-Math.round(rate*.025));hi=Math.min(data.length/2,hi+Math.round(rate*.065));
  const count=hi-lo;if(count<rate*.04)throw Error('Empty speech.');
  let sum=0,peak=0,voiced=0;
  for(let i=lo;i<hi;i++){const x=data.readInt16LE(i*2)/32768;if(Math.abs(x)>.008){sum+=x*x;voiced++;}peak=Math.max(peak,Math.abs(x));}
  // Equalize actors without pumping quiet consonants or making a short shout much louder than a controller.
  const gain=Math.min(2,.8/(peak||1),.115/Math.sqrt(sum/Math.max(1,voiced))),fade=Math.round(rate*.004);
  const out=Buffer.alloc(44+count*2);out.write('RIFF');out.writeUInt32LE(out.length-8,4);out.write('WAVEfmt ',8);out.writeUInt32LE(16,16);
  out.writeUInt16LE(1,20);out.writeUInt16LE(1,22);out.writeUInt32LE(rate,24);out.writeUInt32LE(rate*2,28);out.writeUInt16LE(2,32);out.writeUInt16LE(16,34);out.write('data',36);out.writeUInt32LE(count*2,40);
  for(let i=0;i<count;i++)out.writeInt16LE(Math.round(data.readInt16LE((lo+i)*2)*gain*Math.min(1,i/fade,(count-1-i)/fade)),44+i*2);
  return out;
}
export function validVoiceRequest(v) {
  return v&&typeof v.text==='string'&&v.text.trim().length>0&&v.text.length<=480&&!/[\x00-\x08\x0b\x0c\x0e-\x1f]/.test(v.text)&&
    typeof v.who==='string'&&v.who.length>0&&v.who.length<=96&&typeof v.role==='string'&&/^[a-zA-Z][a-zA-Z0-9_-]{0,31}$/.test(v.role)&&
    (v.urgent===undefined||typeof v.urgent==='boolean');
}
export function createVoiceService({enabled=false,runner}={}) {
  let script,probe,busy=false,bytes=0;const queue=[],cache=new Map();
  const run=runner||((args,signal)=>new Promise((resolve,reject)=>{
    try{script??=windows(path.join(import.meta.dirname,'voice-synthesize.ps1'));}catch(e){reject(e);return;}
    execFile(ps,['-NoProfile','-ExecutionPolicy','Bypass','-File',script,...args],{timeout:8000,maxBuffer:32768,signal},(err,out)=>{
      if(err)return reject(err);try{resolve(JSON.parse(out.replace(/^\uFEFF/,'').trim()));}catch(e){reject(e);}
    });
  }));
  const capability=()=>probe??=(enabled?run(['-Probe']).catch(()=>({available:false,voices:[],reason:'Installed Windows speech voices unavailable.'})):Promise.resolve({available:false,voices:[]}));
  const pump=async()=>{
    if(busy)return;const job=queue.shift();if(!job)return;
    if(job.signal.aborted){job.reject(Error('Cancelled'));return pump();}busy=true;let dir;
    try{
      if(cache.has(job.key)){job.resolve(cache.get(job.key));return;}
      dir=fs.mkdtempSync(path.join(os.tmpdir(),'ngc-voice-line-'));
      fs.writeFileSync(path.join(dir,'request.json'),JSON.stringify(job.request));
      const result=await run(['-Root',windows(dir)],job.signal);
      if(job.signal.aborted)throw Error('Cancelled');
      const wav=prepareSpeechWave(fs.readFileSync(path.join(dir,'line.wav'))),entry={wav,voice:result.voice};
      cache.set(job.key,entry);bytes+=wav.length;
      while(cache.size>64||bytes>16*1024*1024){const key=cache.keys().next().value;bytes-=cache.get(key).wav.length;cache.delete(key);}
      job.resolve(entry);
    }catch(e){job.reject(e);}finally{if(dir)fs.rmSync(dir,{recursive:true,force:true});busy=false;pump();}
  };
  return async(req,res)=>{
    const send=(code,data)=>{if(res.destroyed)return;res.writeHead(code,{'Content-Type':'application/json','Cache-Control':'no-store'});res.end(JSON.stringify(data));};
    if(!/^(127\.|::1$|::ffff:127\.)/.test(req.socket.remoteAddress||'')||req.headers['x-ngc-voice']!=='1')return send(403,{reason:'Local requests only.'});
    if(req.headers.origin){let o;try{o=new URL(req.headers.origin);}catch{}if(!o||o.host!==req.headers.host||!['http:','https:'].includes(o.protocol))return send(403,{reason:'Same-origin requests only.'});}
    if(req.method==='GET')return send(200,await capability());
    if(req.method!=='POST')return send(405,{reason:'Unsupported method.'});
    const cap=await capability();if(!cap.available)return send(503,{reason:'Local voice synthesis unavailable.'});
    const abort=new AbortController();res.on('close',()=>{if(!res.writableEnded)abort.abort();});
    try{
      const chunks=[];let size=0;
      for await(const part of req){size+=part.length;if(size>8192)return send(413,{reason:'Speech line too long.'});chunks.push(part);}
      let input;try{input=JSON.parse(Buffer.concat(chunks).toString());}catch{return send(400,{reason:'Invalid speech request.'});}
      if(!validVoiceRequest(input))return send(400,{reason:'Invalid speech request.'});
      const delivery=deliveryFor(input.who,input.role,input.urgent),voice=cap.voices.includes(delivery.voice)?delivery.voice:cap.voices[0];
      const request={voice,ssml:speechSSML(input.text,delivery)},key=JSON.stringify(request);
      let entry=cache.get(key);
      if(!entry){if(queue.length>=6)return send(429,{reason:'Voice queue full.'});entry=await new Promise((resolve,reject)=>{queue.push({request,key,signal:abort.signal,resolve,reject});pump();});}
      if(res.destroyed||abort.signal.aborted)return;
      res.writeHead(200,{'Content-Type':'audio/wav','Cache-Control':'no-store','X-NGC-Voice-Name':entry.voice,'Content-Length':entry.wav.length});res.end(entry.wav);
    }catch(e){send(503,{reason:abort.signal.aborted?'Speech cancelled.':'Speech generation unavailable.'});}
  };
}
